import{_ as a,C as l,c as i,o as d,a3 as s,G as n,j as e,a as o}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Vendor bills","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/vendor-bills/index.md","filePath":"master/finance/vendor-bills/index.md","lastUpdated":1792041590000}'),h={name:"master/finance/vendor-bills/index.md"};function u(c,t,g,p,f,m){const r=l("ImagePopup");return d(),i("div",null,[t[0]||(t[0]=s('<h1 id="vendor-bills" tabindex="-1">Vendor bills <a class="header-anchor" href="#vendor-bills" aria-label="Permalink to &quot;Vendor bills&quot;">​</a></h1><p>A vendor bill is the invoice you receive from a supplier. You record it in Aureus so your books show what you owe and when it is due. This group follows the bill from the first entry to the final payment.</p><blockquote><p><strong>In simple words:</strong> A bill is the supplier&#39;s invoice, entered on your side. You confirm it, then pay it.</p></blockquote><p>The screens exist in both apps. Use <code>Invoices → Vendors → Bills</code> or <code>Accounting → Vendors → Bills</code>. Each page names both paths.</p><h2 id="record-what-you-owe" tabindex="-1">Record what you owe <a class="header-anchor" href="#record-what-you-owe" aria-label="Permalink to &quot;Record what you owe&quot;">​</a></h2><ol><li><strong>Create the bill.</strong> Click <strong>New Bill</strong> and copy the data from the supplier&#39;s document. The bill starts as a <strong>Draft</strong>.</li></ol>',6)),n(r,{src:"/images1/finance/bill_list.png",alt:"Bills list where you click New Bill"}),t[1]||(t[1]=e("ol",{start:"2"},[e("li",null,[e("strong",null,"Complete the details."),o(" Fill in the "),e("strong",null,"Vendor"),o(", "),e("strong",null,"Bill Date"),o(", "),e("strong",null,"Bill Reference"),o(", "),e("strong",null,"Payment Term"),o(" and the invoice lines.")])],-1)),n(r,{src:"/images1/finance/bill_create_general.png",alt:"New bill with the vendor, bill date, reference and payment term filled in"}),t[2]||(t[2]=e("ol",{start:"3"},[e("li",null,[e("strong",null,"Confirm it."),o(" Click "),e("strong",null,"Confirm"),o(". The bill becomes "),e("strong",null,"Posted"),o(" and the amount you owe is recorded.")])],-1)),n(r,{src:"/images1/finance/bill_view_posted.png",alt:"Posted bill with its header buttons, payment state and totals"}),t[3]||(t[3]=s('<ol start="4"><li><strong>Pay it.</strong> Click <strong>Pay</strong> and register the payment. See <a href="./../payments/register-payment.html">Register a payment</a>.</li><li><strong>Credit it, if needed.</strong> If the supplier credits you, use <strong>Refund</strong>. See <a href="./../customer-invoices/credit-notes-and-refunds.html">Credit notes and refunds</a>.</li></ol>',1)),n(r,{src:"/images1/finance/bill_refund_modal.png",alt:"Create Refund window on a posted bill with Reason, Journal and Date filled in"}),t[4]||(t[4]=s('<p>You can also start a bill from a purchase order. Open a confirmed order and click <strong>Create Bill</strong>. Aureus fills the bill from the order lines. See <a href="./../../supply-chain/purchase/orders/purchase-orders.html">Purchase orders</a>.</p><p>The vendor must exist before you create the bill. See <a href="./../../getting-started/contacts/contacts.html">Vendors</a> and <a href="./../../getting-started/contacts/contacts.html">Contacts</a>.</p><h2 id="states-of-a-bill" tabindex="-1">States of a bill <a class="header-anchor" href="#states-of-a-bill" aria-label="Permalink to &quot;States of a bill&quot;">​</a></h2><ul><li><strong>Draft:</strong> You are still entering data. You can change anything.</li><li><strong>Posted:</strong> You confirmed it. Most fields are locked.</li><li><strong>Cancelled:</strong> You cancelled a draft bill.</li></ul><p>A posted bill also has a <strong>Payment State</strong>.</p><ul><li><strong>Not paid:</strong> Nothing is paid yet.</li><li><strong>In Payment:</strong> A payment is registered and is on its way.</li><li><strong>Partial:</strong> Part of the amount is paid.</li><li><strong>Paid:</strong> The <strong>Amount Due</strong> is zero.</li><li><strong>Reversed:</strong> A refund cancelled the bill.</li></ul><p>The <strong>Amount Due</strong> column shows what is left to pay.</p><h2 id="buttons-by-state" tabindex="-1">Buttons by state <a class="header-anchor" href="#buttons-by-state" aria-label="Permalink to &quot;Buttons by state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Buttons</th></tr></thead><tbody><tr><td>Draft</td><td><strong>Confirm</strong>, <strong>Cancel</strong>, <strong>Delete</strong></td></tr><tr><td>Posted</td><td><strong>Preview</strong>, <strong>Pay</strong>, <strong>Set as Checked</strong>, <strong>Refund</strong>, <strong>Reset To Draft</strong></td></tr><tr><td>Cancelled</td><td><strong>Reset To Draft</strong>, <strong>Delete</strong></td></tr></tbody></table><ul><li><strong>Confirm:</strong> Posts the bill and creates its journal entry.</li><li><strong>Pay:</strong> Registers a full or partial payment.</li><li><strong>Set as Checked:</strong> Marks the bill as reviewed.</li><li><strong>Refund:</strong> Creates a draft refund copied from the bill.</li><li><strong>Reset To Draft:</strong> Reopens the bill for editing. Linked payments are unlinked.</li></ul><h2 id="what-is-different-from-a-customer-invoice" tabindex="-1">What is different from a customer invoice <a class="header-anchor" href="#what-is-different-from-a-customer-invoice" aria-label="Permalink to &quot;What is different from a customer invoice&quot;">​</a></h2><ul><li>You type the <strong>Bill Reference</strong>, which is the number on the supplier&#39;s document.</li><li>The <strong>Bill Date</strong> is required. Aureus does not fill it in for you.</li><li>The <strong>Accounting Date</strong> sets the period in which the bill is recorded.</li><li>The journal is <strong>Vendor Bills</strong>, and bill numbers look like <code>BILL/2026/4</code>. See <a href="./bill-sequence.html">Bill sequence</a>.</li></ul><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./create-bill.html">Create a vendor bill</a>: the bill form, buttons and tabs.</li><li><a href="./bill-sequence.html">Bill sequence</a>: how bill and refund numbers are made.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Unpaid</strong> and <strong>Overdue</strong> views of the bill list to plan your payments each week.</p></div><p>To see all open bills by age, open the <a href="./../reporting/aged-receivable-and-payable.html">Aged payable report</a> in the Accounting app.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../customer-invoices/">Customer invoices</a></li><li><a href="./../payments/">Payments</a></li><li><a href="./../taxes/">Taxes</a></li></ul>',18))])}const _=a(h,[["render",u]]);export{y as __pageData,_ as default};
